// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (DELETE /whoop)
	DisconnectWhoop(ctx context.Context, request DisconnectWhoopRequestObject) (DisconnectWhoopResponseObject, error)
	// WhoopStatus Whether WHOOP can be connected (the server is configured) and whether it is.
	// (GET /whoop)
	WhoopStatus(ctx context.Context, request WhoopStatusRequestObject) (WhoopStatusResponseObject, error)
	// WhoopCallback Complete the connection; back to /track/settings (?whoop=error when it failed).
	// (GET /whoop/callback)
	WhoopCallback(ctx context.Context, request WhoopCallbackRequestObject) (WhoopCallbackResponseObject, error)
	// ConnectWhoop Send the browser to WHOOP to allow access; WHOOP returns it to the callback.
	// (GET /whoop/connect)
	ConnectWhoop(ctx context.Context, request ConnectWhoopRequestObject) (ConnectWhoopResponseObject, error)

	// (DELETE /workouts/{id}/whoop)
	UnlinkWhoop(ctx context.Context, request UnlinkWhoopRequestObject) (UnlinkWhoopResponseObject, error)

	// (GET /workouts/{id}/whoop)
	GetWorkoutWhoop(ctx context.Context, request GetWorkoutWhoopRequestObject) (GetWorkoutWhoopResponseObject, error)
	// LinkWhoop Link a WHOOP activity to a workout, fetching its data (again).
	// (PUT /workouts/{id}/whoop)
	LinkWhoop(ctx context.Context, request LinkWhoopRequestObject) (LinkWhoopResponseObject, error)
	// ListWhoopCandidates The WHOOP activities in [from, to) (the workout's local day), to pick one to link.
	// (GET /workouts/{id}/whoop/candidates)
	ListWhoopCandidates(ctx context.Context, request ListWhoopCandidatesRequestObject) (ListWhoopCandidatesResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

